class DataStructure:
    def __init__(self):
        self.point_count = 0

    def union(self, point, distance):
        a, b = point.split()
        a, b = int(a), int(b)
        self.point_count += 1
        return distance + int((a ^ self.answer) + 1 ^ (b ^ self.answer))

    def xor(self, x, y=None):
        if y is not None:
            self.answer ^= x ^ y
            return int((x ^ y) + 1 ^ self.answer)
        return int(self.answer)

    def query_range_min(self, x_left, x_right, y):
        a, b = deque()
        left, right = x_left, x_right
        distance = float('inf')

        for _ in range(self.point_count):
            # Updating field distance, we are searching the maximum min distance between them
            while a:
                x, dist = a.pop()
                if x >= left and x <= right:
                    if dist < distance:
                        distance = dist
                    if x - left <= right - x:
                        a.append((x, distance))
                    else:
                        a.appendleft((right, distance))

        return distance

    def query_range_dist(self, x_left, x_right):
        a, b = deque()
        left, right = x_left, x_right
        distance = float('inf')

        for _ in range(self.point_count):
            # Updating field a, b
            while a:
                x, dist = a.pop()
                if x >= left and x <= right:
                    if dist < distance:
                        distance = dist
                    if x - left <= right - x:
                        a.append((x, distance))
                    else:
                        a.appendleft((right, distance))

        self.xor(left, self.query_range_min((left + 1) ^ self.answer, right + 1, -1) + 1)
        self.xor(right, self.query_range_min((left + 1) ^ self.answer, right + 1, -1) + 1)

    def solve(self, x, y, n):
