    total_length.append(total_length[-1] + x1)
    for node in range(1, n):
        n_edges += y1
    for node1, node2, weight in edges:
        n_edges -= 1
        n1 = find_node(parent, node1)
        n2 = find_node(parent, node2)
        if n1 == n2:
            continue
        if weight > total_length[n1]:
            n_edges += weight - total_length[n1]
        total_length[n1] = weight
        total_length[n2] = weight
