import math
import sys


def count_paths(n, m, table):
    if n == m:
        return 2  # Both turtles can move in three possible ways
    elif n == 1 or m == 1:
        return 3  # One turtle can move 3 ways, other turtle has only one possible way

    # Pre-computed results
    MOD = 1000000007
    memo = {}

    def dp(x, y, obstacle):
        if x == n and y == m:
            return 0
        if x > n or y > m:
            return 0
        if memo.get((x, y, obstacle)) is not None:
            return memo.get((x, y, obstacle))

        valid_paths = 0
        if table[x][y] == ".":
            valid_paths = dp(x + 1, y, False) + dp(x, y + 1, False)
            valid_paths %= MOD
        elif table[x][y] == "#" and not obstacle:
            valid_paths = dp(x + 1, y, True) + dp(x, y + 1, True)
            valid_paths %= MOD

        memo[(x, y, obstacle)] = valid_paths
        return valid_paths

    obstacle_low, obstacle_high = False, True
    low_paths = dp(1, 1, obstacle_low)
    high_paths = dp(1, 1, obstacle_high)
    totalCount = low_paths * high_paths
    totalCount %= MOD

    return totalCount


if __name__ == "__main__":
    input = sys.stdin.read
    data = str(input().strip())
    n, m = map(int, data.split())
    table = [list(data[i:i + n]) for i in range(0, len(data), n)]
    print(count_paths(n, m, table))
