    for root, indexes in karaoke_tree.items():
        for index, one in indexes.items():
            for two in one:
                parent_index = both[root] + 1
                union(karaoke_tree, root, parent_index)
                both[root] = parent_index
                both[index % k] = parent_index
    return both

def max_score(karaoke_tree, k, max_vertices):
