    max_score_so_far = 0
    N = len(karaoke_tree)

    for kmax in range(k + 1, k * 2 + 1):
        def least_improvable():
            not_improvable = max_score_so_far
            for i in range(len(karaoke_tree)):
                tail = karaoke_tree[i].copy()
                if len(tail) >= kmax:
                    for index, one in tail.items():
                        not_improvable += max(index % kmax - kmax // k, 0)
                elif len(tail) > 1:
                    for parent, child_indexes in tail.items():
                        for child in child_indexes:
                            if parent in karaoke_tree:
                                head_indexes = karaoke_tree[parent]
                                not_improvable += max(
                                    child % kmax - len(head_indexes) // k,
                                    max(0, len(child_indexes) - len(head_indexes))
                                )
            return ((not_improvable + kmax // k) ** 2, not_improvable + kmax // k)

        best = least_improvable()
        max_score_at_k = max(max_score_at_k, best[0])
        max_score_so_far = max(max_score_so_far, best[1] + 1)

    return max_score_at_k

