    word = re.sub(r" +", " ", word)

    for mistake_type in re.findall(r"(\b\w{2,}\b)", word):
        for mistake in ["swap", "skip", "insert", "mistype"]:
            if mistake[0] == "s":
                if mistake in ["swap", "skip"]:
                    partial_word = mistake_type[:2]
                    mistake_type_shortened = " ".join(mistake_type[0]).strip() + mistake_type[2:]
                    wrong_word = partial_word + (mistake_type_shortened[1] if mistake_type_shortened[1].startswith("_") else "_" + mistake_type_shortened[1][1:])
                    if wrong_word not in dictionary:
