from collections import defaultdict

class ManhattanTree:
    def __init__(self):
        self.map = defaultdict(list)

    def add_point(self, x, y, n):
        self.map[(x, y)].append(n)

    def remove_point(self, n):
        self.map[(x, y)].remove(n)

    def query(self, x, y):
        total = 0
        for index, n in enumerate(sorted(self.map[(x, y)], reverse=True)):
            total += n
            self.remove_point(n)
            if not self.map[(x, y)]:
                return total - n

