import math

def find_min_x(a, h, w):
    if a * h < 2 * w:
        return -1  # Infeasible configuration

    total_photos = math.ceil((h - 1) / (2 * a + 1)) * math.ceil((w - 1) / (2 * a + 1))

    # The first row and column can't have a photo with distance x formed between each,
    # as that would mean 2*A*(h-1) + w-1 photos
    if (h - 1) % (2 * a + 1) == 0 and (w - 1) % (2 * a + 1) == 0:
        overlap = (h - 1) // (2 * a + 1) + (w - 1) // (2 * a + 1) - (total_photos - 1)

        if overlap % 2 == 0:
            return overlap / (4 * a + 2)
        else:
            return overlap / (4 * a + 2) / 2
    else:
        edges_left = 4 * a + 2
        return (edges_left - total_photos + 1) / 2

