        if word.isdigit():
            corrected_words.append(word)
            continue

        possible_dict_word = ""
        i, j = 0, 0

        while i < len(word) and j < len(dictionary):
            if word[i:i+1] == dictionary[j]:
                i += len(dictionary[j])
                possible_dict_word += dictionary[j]
                j += 1
            else:
                i += 1

        if j == len(dictionary):
            corrected_words.append(possible_dict_word)
        else:
            corrected_words.append(word)

    return ' '.join(corrected_words)

