    data = input().split()
    n, m = map(int, data[0:2])
    a = [int(num) for num in data[2:2+n]]
    keys = [int(num) for num in data[2+n:2+n+m]]
    gives = [[int(num) for num in data[2+n+m+p:2+n+m+p+m]] for p in range(m)]

    global_max = -1
    for start in range(1 << n):
        used_locks = [0] * m
        end = start
        for i in range(n):
            for lock in range(m):
                if start & (1 << i):
                    if (start & (1 << lock)) == 0:
                        end |= (1 << lock)
        for gear in range(m):
            global_max = max(global_max, calculate_cost(keys, gives, end), calculate_cost(a, a, start | (1 << gear)))

    global_max = -2 * global_max
    if global_max <= 0:
        global_max = -1
    else:
        global_max = [global_max // 2] * m
    print(len(global_max), *global_max, sep=' ')

