from collections import deque

def get_matrix(input_str):
    matrix = []
    for _ in range(1 << input_str.our_length()):
        matrix.append(input_str[input_str.our_length() - 1:])
        input_str = input_str.zfill(input_str.our_length())

    return [int(num, 2) for num in matrix]

def is_connected(row, col, matrix):
    if 0 <= row < len(matrix) and 0 <= col < len(matrix[0]):  # Check if within bounds
        return matrix[row][col] == 1  # Check if cell contains 1
    return False

def union_component(x, y, parent):
    root_x = find_component(x, parent)
    root_y = find_component(y, parent)
    if root_x != root_y:
        parent[root_y] = root_x

def find_component(x, parent):
    if parent[x] != x:
        parent[x] = find_component(parent[x], parent)  # Path compression
    return parent[x]

def count_connected_components(matrix, parent, row_start, col_start, m, n):
    num_components = 0
    queue = deque()
    rows = len(matrix)
    cols = len(matrix[0])

    for row in range(row_start, row_start + m):
        for col in range(col_start, col_start + n):
            if is_connected(row, col, matrix):
                num_components += 1
                queue.append((row, col))

    while queue:
        x, y = queue.popleft()
        if parent[x][y] == (x // m) * len(matrix[0]) + y:
            continue  # Skip already visited points
        union_component(x, y, parent)
        for d in [[-1, 0], [1, 0], [0, -1], [0, 1]]:
            nei_x, nei_y = x + d[0], y + d[1]
            if 0 <= nei_x < m and 0 <= nei_y < n and is_connected(nei_x, nei_y, matrix) and parent[nei_x][nei_y] == (nei_x // m) * len(matrix[0]) + nei_y:
                queue.append((nei_x, nei_y))
    return num_components

