def dfs(matrix, i, j, row, column, visited):
    if i < 0 or j < 0 or i >= row or j >= column or matrix[i][j] == '0' or matrix[i][j] in visited:
        return 0
    visited.add(matrix[i][j])
    directions = [(1, 1), (1, -1), (-1, 1), (-1, -1)]
    for dx, dy in directions:
        dfs(matrix, i + dx, j + dy, row, column, visited)
    return len(visited)

def count_components(n, m, num_matrix):
    component_count = 0
    visited = set()
    for i in range(n):
        for j in range(m // 4):
            if num_matrix[i][j * 4] == '1':
                component_count += dfs(num_matrix, i, j, n, m, visited)
    return component_count

