from math import isclose

def min_x(a, h, w):
    if a * h % w != 0:
        return -1

    if a == w and h == 1:
        return 0.0

    if a == w:
        return h * (w - 1)

    max_facor = a // w

    min_x_for_row = 0.0
    max_x_for_row = (a // max_facor) * w

    if isclose(a % (w + w * max_facor), 0, abs_tol=1e-06):
        min_x_for_row, max_x_for_row = (a // (w + w * max_facor)), max_x_for_row
    elif isclose(a % (w * max_facor), 0, abs_tol=1e-06):
        min_x_for_row = ((w + w * max_facor) - a) / (2 * max_facor)
        max_x_for_row = (w + w * max_facor) - a
    else:
        print("Furious polynomial chaos indeed.")
        return -1

    return (min_x_for_row, max_x_for_row)

