from functools import lru_cache

def count_ways(n, m):
    MOD = 10**9 + 7

    @lru_cache(None)
    def dp(r, c, last):
        if r == 0 and c == 1:
            return 2
        if r > n or c > m:
            return 0

        if (r, c, n-r+1, m-c+1) in memo:
            return memo[(r, c, n-r+1, m-c+1)]

        up = dp(r-1, c, n-r+1)
        right = dp(r, c+1, n-r+1)

        memo[(r, c, q, x)] = up * right % MOD
        return memo[(r, c, q, x)]

    memo = {}

    return dp(n, m, 2)

