    f = [-inf] * N
    q = deque([-inf, inf])

    def push_in_q(x):
        while q and x < q[-1]:
            q.pop()
        q.append(x) 

    for a in A:
        for i in range(N - 1, -1, -1):
            f[i] = f[i] + a if f[i] >= a else a  # Calculate the xor sum
            size = f[i]
            if size:
                peek = push_in_q(size >> 1)
                while peek:
                    _, top = peek
                    peek = push_in_q(a - top)
            push_in_q(f[i])

    xor_sums, size = [], f[0]
    while q:
        _, a = q.popleft()
        if a & 1:
            if size:
                result = size + a - (size >> 1)
                if result not in xor_sums:
