from math import comb
from collections import defaultdict

def count_paths(n, m, table):
    if n == 2 or m == 2:
        return 1

    # Start by counting all possible paths
    paths = [[None for _ in range(m+1)] for _ in range(n+1)]
    for i in range(n):
        paths[i+1][1] = 1
    for j in range(m):
        paths[1][j+1] = 1

    # Define directions
    dirs = [(0, 1), (1, 0)]

    # Simulate movement and calculate paths
    for i in range(2, n+1):
        for j in range(2, m+1):
            for xi, yi in dirs:
                if table[i-xi][j-yi] == ".":
                    paths[i][j] = (paths[i][j] + paths[i-xi-1][j-yi-1]) % 1000000007

    # Count unique paths for each end point
    count = 0
    for start_y in range(1, m):
        for end_y in range(start_y+1, m+1):
            unique_paths = paths[n][end_y-1] * paths[n][m-1] // paths[n][end_y] // (paths[n][end_y-1] + paths[n][m-1] - 1)
            count = (count + unique_paths) % 1000000007

    return count

