def extended_gcd(a, b):
    if a == 0:
        return b, 0, 1
    else:
        gcd, x1, y1 = extended_gcd(b % a, a)
        x = y1 - (b // a) * x1
        y = x1
        return gcd, x, y

def mult_mod(a, b, m):
    return a * b % m

def pow_mod(x, n, m):
    if n == 0:
        return 1
    elif n % 2 == 0:
        return mult_mod(pow_mod(x, n // 2, m), pow_mod(x, n // 2, m), m)
    else:
        return mult_mod(x, pow_mod(x, n - 1, m), m)

