from collections import deque

class Point3D:
    def __init__(self, x, y, z):
        self.x = x
        self.y = y
        self.z = z

class ManhattanPoint:
    def __init__(self, point3d, ans):
        self.point3d = point3d
        self.rows = (point3d.x, point3d.y, point3d.z)
        self.ans = ans

class Adder:
    def __init__(self, X, Y, Q):
        self.X = X
        self.Y = Y
        self.Q = Q
        self.ops = deque()

    def decode_query(self, ans):
        X = (ans - ans)
        Y = (ans - ans)
        N = (ans - ans)
        return X, Y, N

    def process_query(self, query):
        if 'Y' in query:
            ans3d = ManhattanPoint(Point3D(self.X, self.Y, 1), 0)
            X, Y, N = self.decode_query(ans3d.ans)
            if N % 2 == 0:
                X = -X
            if N % 4 == 0:
                Y = -Y
            ans3d.ans = Y ^ ((N * 2 - 1) * X)
            return ans3d.ans
        elif 'M' in query:
            Q -= 1
            ans3d = ManhattanPoint(Point3D(self.X, self.Y, self.Q), -1)
            X, Y, N = self.decode_query(ans3d.ans)
            if N % 2 == 0:
                X = -X
            if N % 4 == 0:
                Y = -Y
            ans3d.ans = Y ^ ((N * 2 - 1) * X)
            return ans3d.ans
        elif 'U' in query:
            ans3d = ManhattanPoint(Point3D(self.X, self.Y, self.Q), 1)
            X, Y, N = self.decode_query(ans3d.ans)
            if N % 2 == 0:
                X = -X
            if N % 4 == 0:
                Y = -Y
            ans3d.ans = Y ^ ((N * 2 - 1) * X)
            return ans3d.ans
        else:
            return ans3d.ans

def decode_input(input_str):
