from heapq import heappush, heappop

def heapify(graph, lengths):
    n = len(lengths)
    m = len(graph)
    result = [0] * n
    level = [[] for _ in range(m)]
    max_heap = []

    for i in range(m):
        heappush(max_heap, (lengths[i], i))

