import re

def fix_errors(text, dictionary):
    words = text.split()
    corrected_words = []
    for word in words:
        correct_word = []
        for char in word:
            char = char.strip(' !?,. ')
            if char in dictionary:
                correct_word.append(char)
            else:
                # Swap missed character
                if char == "?":
                    correct_word.append("!")
                elif char == "!":
                    correct_word.append("??")
                elif char == "?!":
                    correct_word.append("!#", ":???")
            correct_word.append(char)
        corrected_words.append("".join(correct_word))
    return " ".join(corrected_words)

