from collections import defaultdict

def find_parent(parent, node):
    if node not in parent:
        return node
    return find_parent(parent, parent[node])

def union(parent, child, rank):
    if find_parent(parent, child) == find_parent(parent, parent[child]):
        return True
    parent[find_parent(parent, child)] = child
    return False

def largest_score(parent, rank, n, k):
    max_score = 0
    for i in range(1, n + 1):
        for j in range(i + 1, n + 1):
            if union(parent, i, j):
                score = j - i + 1
                max_score = max(max_score, score)
                # Ensure the score does not exceed k
                if score > k:
                    break
    return max_score

