from itertools import permutations

def is_k_lucky(ticket, k):
    for perm in permutations(ticket):
        try:
            expr = eval('+'.join(map(str, perm)))
            if expr == k:
                return True
        except:
            continue
    return False

def generate_k_lucky_combs(length=7, start=0, restrict_digits=None):
    if restrict_digits:
        current_comb = start + list(restrict_digits)
    else:
        current_comb = start
    for i in range(10):
        next_comb = list(current_comb)
        for digit in f'{i:07}':
            next_comb[-1] = ''.join(current_comb + [digit])
            if len(next_comb) < 8:
                next_comb.append(i)
            if len(next_comb) == 8:
                next_comb.append('0')
                yield from generate_k_lucky_combs(length, tuple(next_comb))

def main():
    k, m = map(int, input().split())
    tickets = generate_k_lucky_combs(7)
    tickets = [ticket for ticket in tickets if is_k_lucky(ticket, k)]
    tickets = sorted(tickets)[:m]
    for ticket in tickets:
        print(''.join(map(str, ticket)))

if __name__ == "__main__":
    main()
