from collections import deque

def numSeparatedComponents(grid: str) -> int:
    n, m = len(grid), len(grid[0]))
    connectedComponents = 0
    dx = [-1, 0, 1, 0]
    dy = [0, 1, 0, -1]

    def isRange(x: int, y: int) -> bool:
        return 0 <= x < n and 0 <= y < m

    for i in range(n):
        for j in range(m):
            if grid[i][j] == '1':
                level = [[False] * m for _ in range(n)]
                queue = deque([(i, j)])
                level[i][j] = True
                while queue:
                    x, y = queue.popleft()
                    for k in range(4):
                        nx, ny = x + dx[k], y + dy[k]
                        if isRange(nx, ny) and grid[nx][ny] == '1' and not level[nx][ny]:
                            level[nx][ny] = True
                            queue.append((nx, ny))
                connectedComponents += 1
    return connectedComponents
